CREATE DATABASE `form_app`IF NOT EXISTS;
CREATE TABLE `job_postings` (
  `id` int(11) NOT NULL,
  `job_title` varchar(255) DEFAULT NULL,
  `job_description` text DEFAULT NULL,
  `job_type` varchar(100) DEFAULT NULL,
  `experience` varchar(100) DEFAULT NULL,
  `career_level` varchar(100) DEFAULT NULL,
  `salary` varchar(100) DEFAULT NULL,
  `recruiter` varchar(100) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `category` varchar(100) DEFAULT NULL,
  `state` varchar(100) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `image_path` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `job_postings` (`id`, `job_title`, `job_description`, `job_type`, `experience`, `career_level`, `salary`, `recruiter`, `email`, `category`, `state`, `city`, `image_path`) VALUES
(2, 'Restaurant Accounting Controller – Remote', '<p><strong>Houston</strong></p><p>Job Type: Full-time</p><p>Years of experience: 6+</p><p>Career level: Executive</p><p>Salary: $110-130K</p><p>Want to advise some of the country’s most prestigious and fastest-growing restaurants? Imagine serving and helping various small business clients with their financials but not dealing with the antiquated lifestyle and workstyle of public accounting or the stagnation of an internal accounting department.</p><p>You’ve come to the right place!</p><p>How do we do it?</p><p>The mission of the Outsourced Controller is to provide a frictionless experience for our clients and ensure their financials are delivered accurately, consistently, and timely by managing an accounting team and their work.</p><p>We offer a unique opportunity for a determined, innovative, and process-driven accountant passionate about helping businesses grow and scale in a fast-paced, modern business environment. Our autonomous approach provides a valuable opportunity for self-development. Therefore, we are looking for a driven and determined individual who is open to challenges, excited about the craft, and willing to grow with the firm.</p><p>Duties and Role:</p><ul><li>Ensure accurate, consistent, and timely deliverables to clients</li><li>Serve as the point of contact and advisor to clients</li><li>Manage and oversee weekly and monthly accounting work to ensure staff is preparing successfully</li><li>Ensure proper execution of all work items assigned to each client</li><li>Review monthly financial statement deliverables</li><li>Mentor, manage, and coach Accounting Managers and Team Leads</li><li>Meet with clients virtually</li></ul><p>Key Competencies:</p><ul><li>Ability to articulate and explain financials</li><li>Strong Communicator – written and oral</li><li>Excellence/Quality Focused</li><li>Customer Focus</li><li>Conceptual Ability</li><li>Enthusiasm/Passion</li><li>Analysis Skills</li><li>Empowerment</li><li>Assertiveness</li><li>Likability</li></ul><p>Requirements:</p><ul><li>CPA preferred</li><li>6+ years of work experience</li><li>3+ years managing an accounting team</li><li>3+ years of experience in restaurant accounting or outsourced accounting/Controllership</li><li>Experience with restaurants preferred</li><li>Experience with Marginedge, Restaurant365, and/or QBO preferred</li><li>Confident and comfortable with learning new technology</li><li>Strong organizational and interpersonal skills</li></ul><p>Benefits:</p><ul><li>Telecommuting/remote work</li><li>Unlimited PTO</li><li>Annual budget for self-development and training</li><li>Competitive compensation</li><li>Health insurance</li><li>401-K match</li><li>Collaborative and exciting work environment</li></ul>', 'Part-time', '2', 'manager', '50000', 'Royal', 'ro@gmail.com', 'Fine Dining', 'Rajasthan', 'Rajkot', 'uploads/Restaurants-1.jpg'),
(3, 'Bar manager', '<p><strong>Houston</strong></p><p>Job Type: Full-time</p><p>Years of experience: 6+</p><p>Career level: Executive</p><p>Salary: $110-130K</p><p>Want to advise some of the country’s most prestigious and fastest-growing restaurants? Imagine serving and helping various small business clients with their financials but not dealing with the antiquated lifestyle and workstyle of public accounting or the stagnation of an internal accounting department.</p><p>You’ve come to the right place!</p><p>How do we do it?</p><p>The mission of the Outsourced Controller is to provide a frictionless experience for our clients and ensure their financials are delivered accurately, consistently, and timely by managing an accounting team and their work.</p><p>We offer a unique opportunity for a determined, innovative, and process-driven accountant passionate about helping businesses grow and scale in a fast-paced, modern business environment. Our autonomous approach provides a valuable opportunity for self-development. Therefore, we are looking for a driven and determined individual who is open to challenges, excited about the craft, and willing to grow with the firm.</p><p>Duties and Role:</p><ul><li>Ensure accurate, consistent, and timely deliverables to clients</li><li>Serve as the point of contact and advisor to clients</li><li>Manage and oversee weekly and monthly accounting work to ensure staff is preparing successfully</li><li>Ensure proper execution of all work items assigned to each client</li><li>Review monthly financial statement deliverables</li><li>Mentor, manage, and coach Accounting Managers and Team Leads</li><li>Meet with clients virtually</li></ul><p>Key Competencies:</p><ul><li>Ability to articulate and explain financials</li><li>Strong Communicator – written and oral</li><li>Excellence/Quality Focused</li><li>Customer Focus</li><li>Conceptual Ability</li><li>Enthusiasm/Passion</li><li>Analysis Skills</li><li>Empowerment</li><li>Assertiveness</li><li>Likability</li></ul><p>Requirements:</p><ul><li>CPA preferred</li><li>6+ years of work experience</li><li>3+ years managing an accounting team</li><li>3+ years of experience in restaurant accounting or outsourced accounting/Controllership</li><li>Experience with restaurants preferred</li><li>Experience with Marginedge, Restaurant365, and/or QBO preferred</li><li>Confident and comfortable with learning new technology</li><li>Strong organizational and interpersonal skills</li></ul><p>Benefits:</p><ul><li>Telecommuting/remote work</li><li>Unlimited PTO</li><li>Annual budget for self-development and training</li><li>Competitive compensation</li><li>Health insurance</li><li>401-K match</li><li>Collaborative and exciting work environment</li></ul><p><br>&nbsp;</p>', 'Part-time', '4', 'manager', '60000', 'curtis', 'cu@gmail.com', 'Seafood', 'Gujarat', 'Rajkot', 'uploads/Restaurant-FineDining-1.jpg'),
